# ---------------------------------------------------------------- L2
written("w15_induced_magnetism", 15, 2, "15b",
        stem="A steel paper clip hangs from a bar magnet, and a second clip can be hung from the first. Explain this using induced magnetism.",
        points=[P("the first clip is a magnetic material; the magnet's field magnetises it (induced magnetism)", ["induced magnetism", "induces", "magnetised by the field", "becomes a magnet", "becomes magnetised", "magnetic material"]),
                P("the end of the clip nearest the magnet becomes the opposite pole to the magnet's pole, so it is attracted", ["opposite pole", "unlike pole", "attracted", "attraction", "nearest end becomes"]),
                P("the magnetised first clip then induces magnetism in the second clip in the same way, so it is held too", ["second clip", "in turn", "also becomes a magnet", "magnetises the second", "chain", "same way"])],
        min_points=2,
        model_answer="The paper clip is made of a magnetic material, so the magnet's field magnetises it: this is induced magnetism. The end of the clip nearest the magnet becomes the opposite pole, so the clip is attracted and held. The first clip, now a magnet, induces magnetism in the second clip in the same way, so a chain of clips can be held.",
        hints=["What happens to a magnetic material placed in a magnetic field?",
               "Which pole appears at the end nearest the magnet, and what does that cause?",
               "Explain the induced magnetism and why the second clip also holds."],
        keywords="induced magnetism, opposite pole nearest the magnet, first clip magnetises the second",
        sample_pass=["The magnet induces magnetism in the first clip so its near end is the opposite pole and is attracted; the first clip then magnetises the second",
                     "the clip becomes a magnet by induction and in turn attracts the next clip"],
        sample_fail=["The clips are glued together", "The magnet pulls on the clips' electric charge"])

written("w15_solenoid_field", 15, 2, "15f",
        stem="Fig. 1 shows a solenoid carrying a current. Describe the magnetic field pattern it produces and state two ways of making the field stronger.",
        points=[P("the field is like that of a bar magnet: uniform (parallel lines) inside the coil, looping round outside from one end (N) to the other (S)", ["like a bar magnet", "bar magnet", "uniform inside", "parallel inside", "loops round", "one end north", "north pole at one end"]),
                P("increase the current", ["increase the current", "more current", "larger current", "bigger current"]),
                P("increase the number of turns (or add a soft iron core)", ["more turns", "number of turns", "more coils", "iron core", "soft iron"])],
        min_points=2,
        model_answer="A solenoid produces a field like that of a bar magnet: inside the coil the field lines are parallel and the field is uniform and strong; outside, the lines loop round from the north-pole end to the south-pole end. The field can be made stronger by increasing the current, by increasing the number of turns, or by putting a soft iron core inside the coil.",
        hints=["Compare the pattern with that of a bar magnet.",
               "What two things about the coil or current change the field strength?",
               "Describe the pattern and give two ways to strengthen it."],
        keywords="like a bar magnet, uniform inside; more current, more turns, iron core",
        figure=lambda: sk.solenoid_field(),
        sample_pass=["The field is like a bar magnet's, uniform inside and looping outside; increase the current or the number of turns", "it has a north and south end like a bar magnet; more current and an iron core make it stronger"],
        sample_fail=["The field is circular around the whole coil; make it stronger by using thinner wire", "The field only exists outside the coil"])

written("w15_straight_wire_field", 15, 2, "15f",
        stem="Fig. 1 shows a straight wire carrying a current into the page. Describe the magnetic field around it and state what happens to the field when the current is reversed and when it is increased.",
        points=[P("concentric circles centred on the wire (in a plane at right angles to it), getting weaker / more widely spaced further away", ["concentric circles", "circles around the wire", "circular", "rings", "weaker further away", "further apart"]),
                P("reversing the current reverses the direction of the field (arrows the other way round)", ["reverses the direction", "field reverses", "other way round", "opposite direction", "arrows reverse"]),
                P("increasing the current makes the field stronger (lines closer together)", ["stronger", "closer together", "increases the field", "bigger field"])],
        min_points=2,
        model_answer="The field consists of concentric circles centred on the wire, in planes at right angles to it, becoming weaker further from the wire. Reversing the current reverses the direction of the field lines, and increasing the current makes the field stronger, shown by lines closer together.",
        hints=["What shape are the field lines around a straight wire?",
               "Two changes to the current: its direction and its size. What does each do to the field?",
               "Describe the pattern and both effects."],
        keywords="concentric circles; reverse current → reverse field; more current → stronger",
        figure=lambda: sk.straight_wire_field(True),
        sample_pass=["Concentric circles around the wire; reversing the current reverses the field and a bigger current makes it stronger",
                     "circular field lines; the direction flips if the current flips, and more current gives a stronger field"],
        sample_fail=["Straight lines parallel to the wire; the field does not change", "The field points along the wire"])

written("w15_two_poles_patterns", 15, 2, "15e",
        stem="Fig. 1 shows the field between two unlike poles facing each other. Describe this field, and describe how the field would differ if two like poles faced each other.",
        points=[P("between unlike poles the field lines run straight across from N to S, giving a uniform field (except near the edges)", ["straight across", "from n to s", "uniform", "parallel lines", "north to south", "straight lines between"]),
                P("between like poles the lines bend away from each other and there is a point midway where the field is zero (neutral point)", ["bend away", "curve away", "repel", "neutral point", "zero field", "no field", "lines do not cross", "pushed apart"])],
        model_answer="Between two unlike poles the field lines run straight across from the north pole to the south pole, giving a uniform field, except near the edges where the lines spread out. Between two like poles the lines bend away from each other, and at the midpoint between the poles the field is zero: a neutral point.",
        hints=["Unlike poles attract: picture the lines joining them. Like poles repel: picture the lines pushing apart.",
               "Where could the field be zero between two like poles?",
               "Describe both patterns."],
        keywords="unlike: straight N→S lines, uniform; like: lines bend away, neutral point midway",
        figure=lambda: sk.two_poles(like=False),
        sample_pass=["Between unlike poles the lines go straight across from N to S, a uniform field; between like poles they bend away from each other with a neutral point in the middle",
                     "unlike poles give parallel lines between them; like poles give lines that curve away and a point of zero field"],
        sample_fail=["Both patterns are the same", "Between like poles the lines go straight across"])

written("w15_force_on_conductor_experiment", 15, 2, "15g",
        stem="Describe an experiment to show that a current-carrying wire in a magnetic field experiences a force.",
        points=[P("place a wire (or a light metal rod on two rails) between the poles of a strong magnet, at right angles to the field", ["between the poles", "in a magnetic field", "at right angles", "across the field", "rails", "rod"]),
                P("pass a current through the wire (connect to a cell/switch) and observe that it moves / jumps", ["pass a current", "switch on", "connect a cell", "moves", "jumps", "kicks", "rolls"]),
                P("reversing the current or the magnet reverses the direction of the movement; no current, no movement", ["reverse the current", "reverse the magnet", "turns the magnet round", "moves the other way", "opposite direction", "no current no"])],
        min_points=2,
        model_answer="Place a short length of wire, or a light metal rod resting on two rails, between the poles of a strong magnet so that it is at right angles to the field. Pass a current through it from a cell: the wire jumps or the rod rolls, showing a force. Reversing the current, or turning the magnet round, makes it move the other way, and with no current there is no movement.",
        hints=["You need a magnet, a wire that is free to move, and a way to send current through the wire.",
               "What do you expect to see, and what simple changes confirm the effect?",
               "Describe the set-up, the observation, and the reversal test."],
        keywords="wire between poles at right angles, current → wire moves, reversing current/field reverses motion",
        figure=lambda: sk.flemings_lhr(force=None),
        sample_pass=["Put a rod on rails between the poles of a magnet, pass a current and it rolls; reversing the current makes it roll the other way",
                     "a wire in a magnetic field jumps when the current is switched on and jumps the other way if the magnet is reversed"],
        sample_fail=["Hold a magnet near a wire and see if it attracts it with no current", "Measure the resistance of the wire in the field"])

